`@{u}` 把 PowerShell 解析器搞崩了。改用显式分支名。

[tool-call run_code] {"code": "
const repos = [
 ["My-second-brain", "C:\\Users\\jjq21\\Desktop\\github\\My-second-brain"],
 ["dsh-our-free-model", "C:\\Users\\jjq21\\Desktop\\github\\dsh-our-free-model"],
];
for (const [name, r] of repos) {
 const q = JSON.stringify(r);
 const cmd = [
 "'=== " + name + " ==='",
 "git -C " + q + " status -sb",
 "'--- unpushed ---'",
 "git -C " + q + " log --oneline origin/main..HEAD",
 "'--- last 3 ---'",
 "git -C " + q + " log --oneline -3",
 "'--- stash ---'",
 "git -C " + q + " stash list",
 ].join("; ");
 const res = await tools.pwsh({ command: cmd, description: "Check " + name + " for unpushed work", timeoutMs: 120000 });
 console.log(res.kind === "foreground" ? (res.stdout.text + res.stderr.text) : JSON.stringify(res));
 console.log("");
}
", "description": "Check both repos for unpushed commits and stashes"}

tool_input.code:
const repos = [
  ["My-second-brain", "C:\\Users\\jjq21\\Desktop\\github\\My-second-brain"],
  ["dsh-our-free-model", "C:\\Users\\jjq21\\Desktop\\github\\dsh-our-free-model"],
];
for (const [name, r] of repos) {
  const q = JSON.stringify(r);
  const cmd = [
    "'=== " + name + " ==='",
    "git -C " + q + " status -sb",
    "'--- unpushed ---'",
    "git -C " + q + " log --oneline origin/main..HEAD",
    "'--- last 3 ---'",
    "git -C " + q + " log --oneline -3",
    "'--- stash ---'",
    "git -C " + q + " stash list",
  ].join("; ");
  const res = await tools.pwsh({ command: cmd, description: "Check " + name + " for unpushed work", timeoutMs: 120000 });
  console.log(res.kind === "foreground" ? (res.stdout.text + res.stderr.text) : JSON.stringify(res));
  console.log("");
}
